package com.studybuddy.api.api;
import com.studybuddy.api.api.ApiDtos.*; import com.studybuddy.api.domain.User; import com.studybuddy.api.security.CurrentUser; import com.studybuddy.api.service.AccountService; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/profile")
public class ProfileController { private final CurrentUser current; private final AccountService accounts; public ProfileController(CurrentUser current,AccountService accounts){this.current=current;this.accounts=accounts;} @GetMapping public ProfileResponse get(Authentication a){return accounts.profile(current.require(a));} @PutMapping public ProfileResponse update(Authentication a,@Valid @RequestBody ProfileRequest r){return accounts.updateProfile(current.require(a),r);} @PostMapping("/courses") public ProfileResponse addCourse(Authentication a,@Valid @RequestBody CourseRequest r){return accounts.addCourse(current.require(a),r);} @PutMapping("/availability") public ProfileResponse availability(Authentication a,@Valid @RequestBody List<AvailabilityRequest> r){return accounts.replaceAvailability(current.require(a),r);} }
